  (119, 1, 6, 6, 19, '지능정보사업부', 'AI·데이터 기반 소프트웨어 개발 및 시스템 구축 인턴', '*본 직무는 AI 및 데이터 기반 소프트웨어 개발을 중심으로 다양한 시스템 구축 업무를 수행한다. 주요 업무는 데이터 수집 및 전처리, 간단한 AI 모델 적용 및 테스트, 웹 또는 응용 프로그램 개발 보조, 기존 시스템 유지보수 및 기능 개선 지원 등으로 구성된다. 또한 프로젝트 진행 과정에서 요구사항 분석, 문서 작성, 코드 리뷰 및 테스트 참여를 통해 실제 개발 프로세스를 경험하게 된다.', '*본 인턴십은 컴퓨터공학 전공 학생들이 실제 산업 현장에서 요구되는 소프트웨어 개발 역량과 문제 해결 능력을 체계적으로 습득하도록 하는 것을 목표로 한다.', '- 소프트웨어 개발에 대한 기본적인 이해와 전공지식, 프로그래밍 언어 활용 능력 - 새로운 기술을 학습하고 적용하려는 적극적인 자세 - 책임감과 성실성, 팀원과 원활하게 협업 할 수 있는 의사소통 능력', 'SEMESTER', 'HIRING', DATE '2026-09-01', DATE '2026-12-12', '09:00 ~ 18:00', 40.0, ARRAY['MON', 'TUE', 'WED', 'THU', 'FRI']::varchar(3)[], 'NONE', FALSE, 'MONTHLY', 2156880, ARRAY['MEAL']::varchar(20)[], 1, 'Y3_4', 3.5, 'NONE', 'NONE', NULL, NULL, '소프트웨어학과', FALSE, NULL, NULL, FALSE, 0),
