  (136, 1, 14, 14, 36, '데이터 사업팀', 'AI 학습데이터 구축 및 품질관리 지원', 'AI 학습데이터 구축 프로젝트에서 필요한 데이터 수집, 정제, 라벨링 및 품질 검수(QA) 업무를 수행하여 AI 서비스 개발에 활용되는 학습데이터를 구축하고 품질을 확보한다. 업무는 프로젝트별 작업 가이드와 품질 기준에 따라 담당자의 지도와 피드백을 받아 수행하며, 데이터 관리, 결과물 정리, 작업 현황 관리 등 프로젝트 운영에 필요한 실무 지원 업무까지 담당한다.', 'AI 학습데이터 구축 프로젝트의 전 과정을 이해하고, 데이터 수집, 정제, 라벨링, 품질검수 및 운영 지원 업무를 수행함으로써 AI 데이터 구축 실무 역량과 데이터 품질관리 능력을 습득한다. 또한 실제 프로젝트 수행 과정에서 문제 해결 능력, 협업 능력, 문서화 능력 및 AI 데이터 구축 프로세스에 대한 이해를 향상시키는 것을 목표로 한다.', '작업 가이드와 세부 기준을 정확하게 이해하고 준수할 수 있는 역량이 필요합니다. 꼼꼼한 업무 수행 능력과 기본적인 컴퓨터 활용 능력, 생성형 AI(ChatGPT 등)를 활용하여 업무를 수행하고 피드백을 반영할 수 있는 역량을 요구합니다.', 'SEMESTER', 'EXPERIENCE', DATE '2026-09-01', DATE '2026-12-12', '08:00 ~ 17:00', 40.0, ARRAY['MON', 'TUE', 'WED', 'THU', 'FRI']::varchar(3)[], 'NONE', FALSE, 'MONTHLY', 1650000, '{}'::varchar(20)[], 2, 'Y3_4', NULL, 'NONE', 'NONE', NULL, NULL, '이공계열', FALSE, NULL, NULL, FALSE, 2),
  (137, 1, 15, 15, 37, '경영전략', 'Business Development(BD) 인턴(중국 시장)', '* 실습생은 브랜드의 중국 시장 진출을 위하여 중국 시장 및 사업 리서치를 진행하며, toomuchtax 브랜드와 관련된 업무를 진행한다. * 중국 패션 플랫폼(Douyin, Xiaohongshu), 현지 셀러, KOL, 유통사 등 다양한 시장 참여자를 분석하고, 협업 가능성이 있는 파트너를 선정하여 다양한 채널을 활용하여 컨택하며 미팅 일정 조율 및 커뮤니케이션을 담당한다. * 시장조사부터 잠재 파트너 발굴, 비즈니스 커뮤니케이션, 결과 보고 및 개선 제안까지의 과정을 포함하며, 현업 담당자의 피드백을 통해 단계적으로 실무 역량을 향상시킨다.', '* 중국 패션 시장 및 글로벌 Business Development(BD) 실무를 경험하며 시장조사, 비즈니스 커뮤니케이션 역량을 향상시켜 실무형 인재로 성장하는 것을 목표로 한다.', '- 비즈니스 수준의 중국어 커뮤니케이션 역량 - 중국 시장에 대한 충분한 이해 - 패션/이커머스 분야에 관심 또는 경험 - 열정적으로 업무에 임하는 태도', 'SEMESTER', 'EXPERIENCE', DATE '2026-09-01', DATE '2026-12-12', '10:00 ~ 19:00', 40.0, ARRAY['MON', 'TUE', 'WED', 'THU', 'FRI']::varchar(3)[], 'NONE', FALSE, 'MONTHLY', 2156880, ARRAY['MEAL']::varchar(20)[], 1, 'Y3_4', NULL, 'NONE', 'NONE', NULL, NULL, '경영학부, 중어전공', FALSE, NULL, NULL, FALSE, 0),
  (138, 1, 16, 16, 38, '통역사업부', '통역 프로젝트 매니저', '* 글로벌 수출상담회 등 통역 프로젝트 기획/운영 보조 * 수출상담회 운영·분석 플랫폼(BIS@T)을 활용한 현장 운영 및 상담 실적 집계 지원 * 통역사 풀(eQQui) 관리 및 통역사 사전 교육/매칭 업무 지원', '본 현장실습은 통역 프로젝트 운영 과정에 대한 이해를 바탕으로, 실습생이 통역 프로젝트 관리, 통역사 관리, 수출상담회 운영 지원, 실적 데이터 정리 등 통역사업부의 실무를 경험하도록 하는 것을 목표로 한다.', '* 기본적인 OA 활용 능력: Excel, Word, PowerPoint 활용 가능자 * 능동적이고 긍정적인 태도를 갖추고, 원활한 협업 및 소통이 가능한 자', 'SEMESTER', 'EXPERIENCE', DATE '2026-09-01', DATE '2026-12-12', '09:00 ~ 18:00', 40.0, ARRAY['MON', 'TUE', 'WED', 'THU', 'FRI']::varchar(3)[], 'NONE', FALSE, 'MONTHLY', 1617660, '{}'::varchar(20)[], 1, 'Y4', 3.0, 'NONE', 'NONE', NULL, NULL, '글로벌비즈니스어학부', FALSE, NULL, NULL, FALSE, 0),
  (139, 1, 17, 17, 39, '안전진단팀', '건축물안전진단', '*기존건축물 안전진단
 - 건축물의 현재 상태를 조사하여 잠재된 위험요소의 발생유무를 파악
 건축물의 기능과 안전을 유지하고 재해를 예방
 - 안전진단 대상 건축물 도면(건축도면 및 구조도면) 파악
