 안전진단 현장조사 자료 정리(CAD 및 엑셀 활용)', '*기존 건물축의 안전진단 및 안전점검의 업무 진행 프로세스 이해
*안전진단 및 안전점검업무 지식습득 및 직무역량 향상', '한글워드, 엑셀, 파워포인트, CAD 사용 가능
건축공학 기본 전공과목 이수', 'SEMESTER', 'HIRING', DATE '2026-09-01', DATE '2026-12-12', '09:00 ~ 18:00 (금 09:00 ~ 17:30)', 40.0, ARRAY['MON', 'TUE', 'WED', 'THU', 'FRI']::varchar(3)[], 'NONE', FALSE, 'MONTHLY', 1650000, ARRAY['MEAL']::varchar(20)[], 1, 'Y4', 3.0, 'NONE', 'NONE', NULL, NULL, '토목건축공학과', FALSE, NULL, NULL, FALSE, 0),
  (140, 1, 18, 18, 40, '애브뉴준오 더현대서울점', '미용 시술 보조', '가장 기초적인 고객 샴푸를 선배 인턴들에게 돌아가며 교육 진행 후 실제 고객님 샴푸에 투입 고객 응대를 매장 내 CS담당자에게 시뮬레이션 진행하여 원활한 커뮤니케이션 가능 고객 시술에 필요한 준비과정(펌,염색,케어)를 선배 인턴들과 교육 진행 후 현장 투입 매장 내 환경 관리를 관리자급과 교육 후 환경 시야 넓히기', '미래의 디자이너 양성', '미용 자격증 or 미용 면허증 소지자', 'SEMESTER', 'HIRING', DATE '2026-09-01', DATE '2026-12-12', '11:00 ~ 20:00', 40.0, ARRAY['TUE', 'WED', 'THU', 'FRI', 'SAT']::varchar(3)[], 'NONE', FALSE, 'MONTHLY', 1617660, '{}'::varchar(20)[], 2, 'Y3_4', NULL, 'NONE', 'REQUIRED', 'BEAUTY', '미용 자격증 or 미용 면허증 소지자', '헤어디자인학과', FALSE, NULL, NULL, FALSE, 0)
ON CONFLICT (id) DO UPDATE SET round_id = EXCLUDED.round_id, institution_id = EXCLUDED.institution_id, workplace_id = EXCLUDED.workplace_id, list_seq = EXCLUDED.list_seq, team = EXCLUDED.team, title = EXCLUDED.title, overview = EXCLUDED.overview, education_goal = EXCLUDED.education_goal, competencies = EXCLUDED.competencies, course = EXCLUDED.course, job_type = EXCLUDED.job_type, period_start = EXCLUDED.period_start, period_end = EXCLUDED.period_end, work_hours_text = EXCLUDED.work_hours_text, weekly_hours = EXCLUDED.weekly_hours, weekdays = EXCLUDED.weekdays, overtime = EXCLUDED.overtime, labor_contract = EXCLUDED.labor_contract, stipend_basis = EXCLUDED.stipend_basis, stipend_amount = EXCLUDED.stipend_amount, benefits = EXCLUDED.benefits, headcount = EXCLUDED.headcount, grade_rule = EXCLUDED.grade_rule, gpa_min = EXCLUDED.gpa_min, portfolio = EXCLUDED.portfolio, certificate = EXCLUDED.certificate, certificate_code = EXCLUDED.certificate_code, certificate_text = EXCLUDED.certificate_text, major_text = EXCLUDED.major_text, major_open = EXCLUDED.major_open, closes_on = EXCLUDED.closes_on, close_reason = EXCLUDED.close_reason, closes_on_is_virtual = EXCLUDED.closes_on_is_virtual, final_assigned = EXCLUDED.final_assigned;

-- 자격증: seed에서 빠진 코드는 직무 upsert 뒤에 지운다(FK). 프로필이 쓰는 코드는 남긴다(ADR-0021)
DELETE FROM certificate c WHERE c.code NOT IN ('BEAUTY', 'ACCOUNTING')
  AND NOT EXISTS (SELECT 1 FROM job j WHERE j.certificate_code = c.code)
  AND NOT EXISTS (SELECT 1 FROM student_profile sp WHERE c.code = ANY (sp.certificates));

-- 사는 곳: seed에서 빠졌지만 프로필이 쓰고 있어 남은 행은 목록 맨 뒤로
UPDATE area a SET sort_order = 30000 + s.n
  FROM (SELECT code, row_number() OVER (ORDER BY code) AS n FROM area WHERE sort_order < 0) s
  WHERE a.code = s.code;

