  (115, 1, '1~2주차', '1. OJT, 담당 사업군 및 관련 상품, 콘텐츠의 이해 및 관리 교육 2. 업무 기본 역량 교육 (커뮤니케이션, 프로젝트 관리, 인트라빗 교육) 3. 영상 디자인 업무에 필요한 Adobe Tool 활용 교육 (포토샵, 일러스트) 4. 강의 제작 스튜디오 현장 교육 및 촬영 교육'),
  (115, 2, '3-5주차', '1. 해커스캠퍼스 채널 섬네일 디자인 작업 1. 영상 디자인 업무에 필요한 Adobe Tool 심화 교육 (프리미어 프로, 애프터이펙트) 2. 영상 디자인 업무에 필요한 AI 활용 교육 (ChatGPT, Midjourney) 3. 해커스캠퍼스 채널 과정 소개 페이지 디자인 작업'),
  (115, 3, '4~6주차', '1. 해커스캠퍼스 직무 교육 콘텐츠 영상 촬영 보조 및 편집 작업 2. 해커스캠퍼스 마이크로러닝 콘텐츠 영상 편집 작업 3. 해커스캠퍼스 숏폼 콘텐츠 영상 편집 작업'),
  (115, 4, '7~10주차', '1. 해커스캠퍼스 직무 교육 영상 자막 디자인 작업 2. 캠타시아 촬영 직무 교육 콘텐츠 과정 영상 디자인 작업 3. 전자칠판 촬영 직무 교육 콘텐츠 과정 영상 디자인 작업'),
  (115, 5, '11~14주차', '1. 블루스크린 촬영 직무 교육 콘텐츠 과정 영상 디자인 작업 2. 스튜디오 촬영 직무 교육 콘텐츠 과정 영상 디자인 작업 3. 직무 교육 타이틀 인트로 영상 디자인 작업'),
  (115, 6, '15주차', '1. 디자인 업무 활용 소스 정리 및 마무리 작업 2. 업무 인수인계서 작성'),
