  (135, 6, '11~12주차', '성분, 주의사항 등 변경에 따른 국/영/중문 패키지 문안 텍스트 데이터 업데이트 보조 및 시즌성 기획 세트 패키지 배리에이션 지원'),
  (135, 7, '13~14주차', '양산 제품의 최종 인쇄 데이터 검증 및 유관 부서(상용화팀/마케팅팀) 협업을 통한 패키지 가이드라인 최신화 작업 참여'),
  (135, 8, '15~16주차', '실습 기간 내 작업한 디자인 자산 최종 검수 및 포트폴리오 아카이빙, 인턴십 최종 성과 보고 및 지도 종료'),
  (136, 1, '1~2주차', '회사 및 프로젝트 소개, 정보보안·개인정보 보호 교육, AI 학습데이터 구축 프로세스 및 업무 가이드 교육'),
  (136, 2, '3~4주차', '프로젝트 요구사항에 따른 데이터 수집 업무 수행 및 수집 기준 이해'),
  (136, 3, '5~6주차', '데이터 수집 업무 심화 및 데이터 정제 업무 수행, 결과 피드백'),
