  (416, 6, NULL, 119, 'competencies', '- 소프트웨어 개발에 대한 기본적인 이해와 전공지식, 프로그래밍 언어 활용 능력 - 새로운 기술을 학습하고 적용하려는 적극적인 자세 - 책임감과 성실성, 팀원과 원활하게 협업 할 수 있는 의사소통 능력', 2, '- 소프트웨어 개발에 대한 기본적인 이해와 전공지식, 프로그래밍 언어 활용 능력'),
