  (584, 8, NULL, 127, 'majorRequirement', '글로벌 비즈니스어학부(영어), 광고홍보콘텐츠학과 중 2명', 4, '글로벌 비즈니스어학부(영어), 광고홍보콘텐츠학과 중 2명'),
