  (802, 14, NULL, 136, 'competencies', '작업 가이드와 세부 기준을 정확하게 이해하고 준수할 수 있는 역량이 필요합니다. 꼼꼼한 업무 수행 능력과 기본적인 컴퓨터 활용 능력, 생성형 AI(ChatGPT 등)를 활용하여 업무를 수행하고 피드백을 반영할 수 있는 역량을 요구합니다.', 2, '작업 가이드와 세부 기준을 정확하게 이해하고 준수할 수 있는 역량이 필요합니다. 꼼꼼한 업무'),
