  (139, 'MAJOR', 'INSTITUTION_LIST', '2026학년도 2학기 표준 현장실습학기제 참여기관 리스트', NULL, '전공 : 토목건축공학과'),
  (139, 'GPA', 'INSTITUTION_LIST', '2026학년도 2학기 표준 현장실습학기제 참여기관 리스트', NULL, '학점 3.0 이상'),
  (140, 'GRADE', 'INSTITUTION_LIST', '2026학년도 2학기 표준 현장실습학기제 참여기관 리스트', NULL, '학년 : 3, 4학년'),
