  (140, 'CERTIFICATE', 'OPERATION_PLAN', '애브뉴준오 더현대서울점 운영계획서', 2, '미용 자격증 or 미용 면허증 소지자');

-- testimonial 17행
INSERT INTO testimonial (id, source_document_id, institution_id, team_text, activities, outcomes, page, one_line, company_intro, results, reflection, major_text, grade_text) VALUES
  (1, 19, 4, '강의제작팀', ARRAY['촬영자료(PPT) 제작 및 검수', '강의 검수', '학습자료 제작', '샘플 강의 / 홍보영상 선정', '목차 작업 / 오픈 작업', '강의의 CS 관련 작업이나 수정 작업 등 기타 작업', '공모전 참여']::text[], ARRAY['많은 강의를 담당하여 오픈을 진행']::text[], 1, '성장의 기회', '(주) 챔프스터디는 해커스 교육그룹으로, 고객의 다양한 니즈에 맞춘 체계화된 커리큘럼과 세분화된 프로그램으로 교육업계에서 대표적인 그룹으로 자리 잡았습니다.

강의제작팀의 핵심 가치는 완성도 높은 강의를 향한 집념과 더 나은 강의를 위한 비판 정신, 고객의 입장에서 생각하는 강의 검수, 담당 강의에 대한 책임감과 업무 기한 준수입니다.', '콘텐츠 제작 능력을 키울 수 있었고, 강의 담당자로서의 책임감을 느끼며 업무를 수행하는 자세를 갖출 수 있었습니다. 여러 업무를 담당하며 업무 관리 능력과 목표 달성 능력을 키울 수 있었습니다. 또한 문제 상황에서 문제를 대처할 수 있는 문제 해결 능력도 기를 수 있었습니다.

실습 기간 동안 많은 강의를 담당하여 오픈을 진행하면서 강의 하나하나가 잘 마무리되었다는 것을 확인할 때마다 뿌듯함을 느꼈습니다.', '저는 처음에는 마땅한 스펙이 없었지만, 현장실습을 통해 실무 경험을 쌓을 수 있는 기회를 얻었습니다. 세 달 동안 이 기회를 통해 관심 있던 분야를 직접 경험해 볼 수 있었고, 업무 역량을 쌓으며 성장할 수 있었습니다.

제가 직접 업무하는 것뿐만 아니라 상사분들을 보고 또 다양한 이야기를 듣는 것도 좋은 경험이 되었습니다. 이후에 취업할 때도 현장실습 동안의 경험이 도움이 많이 될 거라고 느껴졌습니다.', '경영학부', '4학년'),
  (2, 19, 3, 'OL디자인팀', ARRAY['디자이너별 작업 지시서 분류', '샘플 관리', '작업 지시서 작성', '의상 제작', '부자재 셀렉', '업체에 생산 요청', '수정사항 정리 및 1차 품평 진행']::text[], '{}'::text[], 3, '등불', '세정은 올리비아 로렌, 비비 올리비아, 웰메이드 등 다양한 브랜드를 보유한 국내 패션 유통 기업입니다.

OL디자인팀은 올리비아 로렌의 브랜드 이미지에 맞는 차분하고 여성스러운 의류를 선보이고 있으며, 꾸뛰르 라인 또한 매 시즌 발매하고 있습니다.
매 시즌마다 컬렉션 방향을 잡고 디자인 리서치, 아이디어 회의, 작업지시서 작성, 샘플 제작, 수정, 최종 샘플 확정의 순서로 일이 진행됩니다.', '디자인실이 어떻게 운영되는지 직접 겪으며 배울 수 있었습니다. 시즌을 준비하는 과정, 업체와의 컨택 방법 등 향후 회사 생활에 도움이 될 수 있는 많은 것들을 배울 수 있는 좋은 기회였다고 생각합니다.

많은 부서들과의 교류를 통해 협업 능력과 다양한 비즈니스 매너들을 배울 수 있는 기회였으며, ''내 옷''을 처음부터 끝까지 하나하나 신경써가며 만드는 과정에 즐거움을 느낄 수 있었습니다.', '어디로 가야할지 고민이 많았던 나의 발 아래에 나타나 방향을 알려주는 등불과도 같다고 느꼈습니다.

해당 직무가 본인에게 딱 맞으리라는 보장도 없을뿐더러, 짧은 기간 동안 인생이 180도로 바뀌는 일은 사실상 희박합니다. 하지만 그 외의 다양한 것들을 배울 수 있고, 직무에 집중하면서 다양한 가능성을 찾아보는 시간을 가진다면 그것 또한 뜻깊은 시간이 될 수 있다고 생각합니다.', '공연예술학부 무대패션전공', '3학년'),
  (3, 19, 7, '마케팅&제품개발팀', ARRAY['영상 기획 및 제작', '인스타그램 팔로워와의 소통 업무', '브랜드 계정 재활성', '프로모션& 광고 기획', '인플루언서 마케팅 진행', '스킨케어 라인 신제품 개발']::text[], ARRAY['자유롭게 마케팅 아이디어를 제안']::text[], 9, '목표 달성을 위한 첫 걸음', '(주)원오세븐은 전통 발효 기법과 현대 과학의 만남으로 탄생한 스킨케어 브랜드입니다. 소통 능력과 능동적이고 진취적인 태도를 가진 글로벌 인재를 추구합니다.

마케팅&제품개발팀에서는 SNS 콘텐츠를 기획 & 제작하여 소비자들과 소통하고 광고, 인플루언서 관리 등을 통해 브랜드와 제품을 알리는 역할을 합니다. 또한 트렌드와 브랜드 가치에 맞는 상품을 기획하고 개발하는 직무를 수행합니다.', '자유롭게 마케팅 아이디어를 제안하여 능동적인 업무 태도와 콘텐츠 제작 능력을 인정받았습니다. 한국을 넘어 글로벌 마케팅까지 업무의 분야를 넓히고 새로운 업무 경험들을 할 수 있는 기회가 생겨서 뿌듯하고 기뻤습니다.

그동안 저의 목표 직무를 위해 배웠던 전공지식을 직접 실무에 적용해보며 마케팅이라는 것이 트렌드를 따라가는 것도 중요하지만 근본적인 브랜드 컨셉은 놓치지 않아야 한다는 것을 느꼈습니다.', '현장실습학기제를 통해 한 기업의 일원으로서 전공 지식과 그동안의 경험, 능력을 실무에 적용하여 브랜드가 성장하는 과정에 함께할 수 있어서 의미있는 경험이였습니다.

마케팅이라는 직무는 꾸준히 트렌드에 관심을 가지고 해당 직무에 대한 경험, 아이디어 능력이 축적되어 있어야 하는 분야라고 생각합니다. 실무 경험이 없으시다면 현장실습학기제에 지원해보시는 것을 추천드립니다.', '헤어메이크업디자인학과', '4학년'),
  (4, 19, 11, '사업부', ARRAY['결과보고서, 수요기술조사서 작성 후 업로드', 'DBN, 델타텍코리아 웹사이트 관리', '행사 및 프로젝트 미팅 참가 시 통역 및 회의록 작성', '매주 과학기사 5개 번역', 'EEN 기술 프로파일 피드백 및 등록', '국내/외 기업과 유선 및 이메일 연락사무', '글로벌화 프로젝트 지원 업무']::text[], ARRAY['많은 국내 기술 기업들의 프로필을 보고 매치 메이킹 등 업무를 진행']::text[], 11, '방향', '(주)델타텍코리아는 기술 무역 회사로서, 국내 기술 기업들의 해외 진출을 돕고 네트워크 구축을 돕는 기업입니다.

사업부는 회사의 근본적인 업무의 중추인데, 기본적으로 매치메이킹을 하고, 이를 통한 미팅에서 통역 및 연락사무의 역할을 담당합니다. 해외기업들의 Request를 듣고 국내 기술 기업들을 연결해줍니다. 이 외에 여러 국가 프로젝트에 무역 중개업을 담당합니다.', '무역 네트워크 산업에 대해 처음으로 자세히 알게 되었으며 실무가 어떠한 형식으로 이뤄지는지 알게 되었을 뿐만 아니라, 직접 실무를 뛰며, 프로젝트 진행을 맡기도 했습니다.

업무 시 무조건적으로 영어를 쓰고, 해외기업과의 연락 사무를 경험해야했기에 비즈니스 영어를 배울 수 있었습니다. 뿐만아니라, 직접 많은 국내 기술 기업들의 프로필을 보고 매치 메이킹 등 업무를 진행하다 보니 좋은 기술 사업들을 찾아볼 수 있는 계기가 되었습니다.', '해외 무역 및 마케팅 직무를 취업연계중점대학에서부터 경험하면서, 이 직무가 나와 성향상 잘 맞는다고 생각하게 되었으며, 이번 현장실습을 4달간 참여하면서 더욱 마음을 강고히 하게 되었습니다.

기존에 세무 직무를 생각하고 있었지만 해외 영업 직무가 내게 더 맞는다는 확신을 가지게 되었으며, 직무에 대한 장단점 및 향후 진로에 필요할 여러 가치관을 생성하는데 매우 좋은 방법이라 생각합니다.', '경영학부', '3학년'),
  (5, 20, 9, '콘텐츠팀', ARRAY['SNS 게시글 콘텐츠 기획 및 자료 수집', 'SNS 게시글 광고 게재 및 성과 지표화 업무', '수치를 바탕으로 효과적인 게시글 작성법 습득', '콘텐츠 기획 및 작성, 디자인 툴 실전 적용', '애플리케이션에 게재되는 배너 및 홍보물 디자인 제작']::text[], '{}'::text[], 7, '안경', '위아프렌즈는 ''소통의 장벽을 허물어 전 세계 사람들을 친구로 만들어 주자!''라는 비전을 바탕으로 ''트리 프렌드''라는 외국어의 장벽을 허무는 서비스를 통해 전 세계 사람들과 친구가 될 수 있는 소통의 장을 제공하는 기업입니다.

콘텐츠팀에서는 매주 외국인을 대상으로 한국의 여행지에 대해 소개하는 콘텐츠를 제공합니다. 주로 칼럼 형식의 콘텐츠와 이를 바탕으로 SNS에 업로드하는 카드 뉴스 형식의 콘텐츠가 있습니다.', '더 다양하고 많은 업무를 맡게 되면서 힘든 순간도 많았지만, 결과물이 나왔을 때의 뿌듯함은 이루 말할 수 없었습니다. 전공에서 배웠던 리플릿 등 인쇄물 제작 경험을 활용할 수 있는 기회가 있어 전공 지식을 실무에 적용하는 재미를 느꼈습니다.

취업연계에 이어 같은 기업에서 실습하면서 기존 업무에는 익숙해졌다고 생각했지만, 추가적인 업무를 맡게 되면서 보완할 부분이 많다는 것을 깨달았습니다. 이를 보완하기 위해 지속적으로 연구하고 노력할 것입니다.', '뿌옇고 흐리게만 보이던 것들을 명확하게 바라보고 앞으로 나아갈 수 있게 돕는 안경처럼, 현장실습은 앞으로 직무적인 부분뿐만 아니라 인생에서 제가 앞으로 어떻게 나아가고 싶은지를 보고 생각할 수 있도록 해주는 좋은 기회였습니다.

아직 막막하고 뿌연 길을 헤매고 계신 분들께도 좋은 길잡이가 되어줄 것이라 생각합니다. 면접도 업무도 아직 신입인 저희를 위해 많이 배려해 주시므로 조금만 용기를 내서 참여해 보시기 바랍니다.', '광고홍보콘텐츠학과', '4학년'),
  (6, 20, 11, '사업부', ARRAY['기술 제품 이해 및 시장 동향 조사', '시장 조사 데이터를 DB 형태로 정리', '산업 Value-Chain 이해 및 목표 고객 선정', 'Sales Pipeline 작성 및 잠재 고객 목록 작성', '무역 거래 문서 작성', '잠재 고객 타색 및 목록 작성', '해외 수요 기업 발굴', '기술 판촉 활동 결과 정리', '보고서 기반하여 기술 판촉 성과와 개선 방향 도출']::text[], ARRAY['잠재 고객을 성공적으로 발굴', '기술 소개서를 작성', '데이터베이스 구축 및 관리']::text[], 13, '성장의 발판', '델타텍코리아는 e-기술 무역대행사로. 외부 기술을 도입·활용해서기업 성장을 촉진하려는 개방형 혁신을 가속화하는 글로벌 기업의 창업회사와 연구기관을 상호 연계·성장하려는 혁신중개시장에 적극 참여하는 회사입니다.

사업부는 글로벌 시장에서 국내 기업의 기술과 제품을 효과적으로 소개하고, 해외 거래선을 발굴하며, 기술 판촉 활동을 통해 국제적인 비즈니스 기회를 창출하는 역할을 수행합니다.', '이번 디지털 무역 실습을 통해 글로벌 시장에서의 비즈니스 과정을 직접 경험할 수 있었습니다. 시장 조사와 마케팅 활동, 고객 발굴 과정에서 디지털 플랫폼을 효과적으로 활용하는 방법을 익혔으며 잠재 고객을 성공적으로 발굴하고, 기술 소개서를 작성하는 과정에서 실질적인 결과물을 만들어냈다는 점이 가장 기억에 남습니다.

데이터베이스 구축 및 관리, 무역 거래 문서 작성 방법 등을 통해 전공 지식을 습득했고, 의사소통 능력 및 실무에 필요한 역량과 업무 태도에 대해 배웠습니다.', '현장실습은 실질적인 업무 경험을 쌓을 수 있는 귀한 기회였습니다. 실습에 참여했을 때는 열린 마음으로 배우려는 자세와 성실한 태도로 임했습니다. 처음에는 낯설고 어려운 점도 있었지만, 적극적으로 참여하고 책임감을 가지고 임하다 보니 많은 것을 배울 수 있었습니다.

이런 경험을 토대로 제가 한 단계 더 성장할 수 있었던 것 같습니다.', '금융정보공학과', '4학년'),
  (7, 20, 7, '마케팅팀', ARRAY['서포터즈 관리 및 선발', 'SNS 계정 관리 및 업로드', '인플루언서 시딩 리스트업', '콘텐츠 기획 및 제작', '국내외 광고 제작', '팝업 이벤트 기획: 팝업 컨셉 및 슬로건 기획', '팝업 서포터즈', '외부 미팅 참여 및 거래처 이미지 업로드']::text[], ARRAY['팝업 이벤트를 기획해 발표', '아이디어가 그대로 적용']::text[], 15, '길라잡이', '원오세븐은 미생물 발효과학을 적용시켜 효능이 입증된 효능 원료의 밸런스를 유지하는 시너지 원료를 사용하여 스킨케어 제품을 만드는 기업입니다. 또한 우리만의 오랜 전통이 담긴 천연발효 식초를 바탕으로 피부 자극을 최소화하면서도 완벽한 사용감을 안겨주는 제품을 만드는 데 집중하고 있습니다.

마케팅팀은 국내 마케팅의 전반적인 업무를 담당하고 있으며 서포터즈 관리 및 선발, SNS 계정 관리 및 업로드 등 다양한 마케팅 업무를 도맡아 합니다.', '마케터는 이론공부보다는 현장에서 발로 뛰는 성격이 강한 것을 느꼈고 MD업무를 더 심화하여 배우기 위해서는 무역에 대한 이론 공부가 더 필요하다는 것을 느껴 학교에 돌아가 무역 수업을 수강해야겠다고 생각했습니다.

입사하자마자 팝업 이벤트를 기획해 발표하였는데 저의 아이디어가 그대로 적용되었고 실제 손님분들이 잘 즐겨주시는 모습을 보니 의미있고 뿌듯한 경험이었습니다.', '2년 동안 대학 생활을 하며 배우고 있는 전공과목들이 실무에서 어떻게 쓰이는지 감이 잡히지 않아 ''취업''이라는 단어가 그저 멀게만 느껴졌습니다. 하지만 현장실습 학기제를 통해 향후에 취업하게 되면 어떻게 일하게 되는지 전공과목의 활용방법을 알 수 있게 되어 앞으로 영어 실력 향상과 무역 심화 전공과목 이수를 목표로 설정하였습니다.

취업에 대해 무지하다 하더라도 열정과 자신감만 있으면 누구든지 도전해도 좋을 좋은 기회입니다.', '경영학부', '3학년'),
  (8, 20, 17, '안전진단팀', ARRAY['어린이집 건축물 안전진단 후 결함 위치 도면 그리기 및 결과보고서 작성', 'OOO 건축물 외관 그리기 작업', '건축물 외관 조사 부록 정리, 결과표 정리', '건축물 보수작업에 필요한 재료 조사', 'MIDAS 프로그램 배우고 활용하기', '그 외 자료 및 보고서 정리 등']::text[], '{}'::text[], 19, '알을 깨게 만드는 시작', '빌딩닥터엔지니어링은 기술 인력의 자질향상 및 전문인력의 확보와 더불어 연구 개발 교육에 주력하고 있습니다. 최상의 전문가집단과 최신 장비를 활용하여 신뢰성 있는 결과를 제시하는 엔지니어링 회사로. 건축물의 구조컨설팅과 안전진단 현장 기술 지원 등 기술력을 바탕으로 경제적이고 합리적인 솔루션을 최상의 엔지니어링 서비스로 제공합니다.

안전진단팀은 건축물의 현 상태를 조사하여 잠재된 위험 요소의 발생 유무를 파악하며 건축물의 기능과 안전을 유지하고 재해를 예방합니다.', '전공책이나 기사 문제집에서 사진이나 문자로만 보던 장비들을 직접 만져보고 다룰 기회가 생겼습니다. 장비들을 어떻게 다루는지 알고자 하는 필요한 정보를 얻기 위해 어떤 장비를 사용해야 하는지를 알게 되었습니다.

학교에서 ''마이다스'' 프로그램을 특별강의로 2번 정도 접해보았습니다. 회사 업무에서도 이 프로그램이 유용하게 잘 쓰이고 있었으며 잘 활용할 줄 알아야 한다는 것을 알게 되었습니다. 회사 선임분들의 도움을 받아 더 이상 ''접해보았다''가 아닌 ''할 수 있다''로 바뀌게 되었습니다.', '''학생''이라는 신분을 벗어나 ''사회인''으로 세상으로 나아가기 전 꼭 필요한 시간이라고 생각합니다. 실수하더라도 어느 정도 학교라는 울타리 안에서 보호를 받을 수 있고 학생과 실습생으로 이해를 받고 용서를 받을 수 있으면서 현장에 필요한 자세나 마음가짐, 여러 사람들과의 만남 속에서 무언가를 배우기에 정말 좋은 환경이라고 생각합니다.

''학생''은 배우는 사람입니다. 아직 많은 것을 알지 못하고 무엇이든 배우려고 하는 학생에서 기대치가 높지 않습니다. 두려워하지 않고 도전하였으면 좋겠습니다.', '토목건축공학과', '4학년'),
  (9, 21, 10, '마케팅솔루션 2팀', ARRAY['전반적인 사내 업무 프로세스 파악 (견적서, 예산서, 정산서 작성 및 제안서, 계약서 작성)', '사내 아웃바운드 진행', '미쉐린 코리아 기업 행사 운영 기획서 작성', '2025 렛츠런파크 어린이 놀자 페스티벌, 브레드이발소/엄마까투리 싱어롱쇼 계약 담당', '태백시 날아라 새들아, 슈퍼윙스 퍼레이드 계약 담당', '천안 흥타령 춤축제, 샌드박스 계약 진행중']::text[], ARRAY['''천안 K-컬처박람회'' 내 캐치! 티니핑 키즈존 기획까지 맡아 진행', '기획 보조 업무']::text[], 5, '고생 끝의 낙', '스미스 주식회사는 오프라인 & 온라인 프로모션 대행업체입니다. 캐릭터 IP를 활용한 키즈존 운영, 뮤지션과 인플루언서 섭외 공연 등 오프라인 프로모션을 기획부터 행사 운영까지 전반적으로 담당하고 있습니다. 또한 유튜브, 인스타그램 등 소셜미디어를 활용하여 브랜디드 콘텐츠(BDC) 및 PPL 등 다양한 온라인 프로모션도 함께 전개하고 있습니다.

마케팅 솔루션 팀의 경우 다양한 분야의 입찰 사업 진행 및 캐릭터 활용 키즈존 공간 조성 프로젝트 진행을 담당하고 있습니다.', '단순한 인턴으로 시간을 보낸 것이 아니라, 실무자의 입장에서 기획 보조 업무부터 시작하여 메인 PM으로서 문화도시 천안에서 진행된 대규모 행사인 ''천안 K-컬처박람회'' 내 캐치! 티니핑 키즈존 기획까지 맡아 진행하였습니다.

이를 통해 전반적인 회사 생활에 대한 이해도를 높일 수 있었으며, 향후 하계 취업연계 프로그램에도 연속으로 참여한 뒤 정직원 입사를 앞두고 있습니다. 대학생 신분으로는 경험하기 어려운 다양한 프로젝트에 직접 참여할 수 있어 매우 뜻깊은 경험이었습니다.', '성적이나 자격증과 같은 기본적인 스펙도 물론 중요하지만, 실제로 회사에서 근무해보니 무엇보다도 실무 경험과 경력이 가장 큰 경쟁력이라는 것을 직접 체감할 수 있었습니다. 대학생이라는 신분일지라도 두려워하지 말고 다양한 도전에 나서며,

때로는 실수를 통해 배우고 성장해 나갈 수 있는 이 소중한 기회를 꼭 잡으셨으면 좋겠습니다. 이러한 경험 하나하나가 향후 진로를 결정하고 사회에 나아가는 데 큰 자산이 될 것이라 믿습니다.', '광고홍보콘텐츠학과', '4학년'),
  (10, 21, 7, '물류팀', ARRAY['내부재고 관리, 물류창고 재고, 이동중인 재고, 해외재고 관리', '수출 준비 참여', '인터넷 판매건 출고시키기', '물류비 절감 방안 생각', '물류비 기록', '해외로 보내지는 물류비들이 오차가 없는지 비교하기 위해', '모든 물류비를 기록하고 영수증과 비교함']::text[], ARRAY['해외 운송비를 절반 이상 줄일 수 있는 방안을 직접 조사하고 PPT로 제안']::text[], 9, '실전', '107은 가문 대대로 내려오는 107가지의 비방을 바탕으로 천연발효식초를 화장품 원료화하여 클렌징과 스킨케어 제품으로 개발 판매하는 스킨케어 브랜드입니다. 예로부터 한애가 천연발효식초 제조장의 장인들은 피부가 젊고 밝으며 부드러웠습니다. 이에 착안하여 약사이자 국내 최대 천연발효식초명at 한애가제조장(製造場)을 맡고있는 장인이 평균 7년 이상 발효 숙성시킨 최상급 천연발효식초를 원료화하여 프리미엄 식초 화장품을 개발했습니다. 장인정신과 첨단 연구가만나 모든 여성들의 아름다운 피부 케어에 도움이 될 수 있는 스킨케어 브랜드원오세븐이 탄생하게 되었습니다.', '실질적으로 물류의 시작부터 끝까지의 과정에 직접 참여해보니, 이론으로 배울 때보다 훨씬 더 중요하고 복잡하다는 것을 느꼈습니다. 초반에는 실무에 대한 긴장감이 컸지만, 지금은 회사에 잘 적응하며 제 역량을 점점 더 보여드릴 수 있었습니다. 마케팅팀과의 정기적인 회의를 통해 불필요한 재고가 발생하지 않도록 관리하는 방법에 익숙해졌고, 주간 물류회의를 통해 재고를 효율적으로 운영하는 법도 배웠습니다. 특히, 가장 중요한 과제인 물류비 절감과 관련해 해외 운송비를 절반 이상 줄일 수 있는 방안을 직접 조사하고 PPT로 제안드린 결과, 해당 방안이 채택되어 실제 비용 절감으로 이어지는 성과를 낼 수 있었습니다.', '학교에서 이 실전에 나가기 위해서 3년이란 시간동안 다양한 전공 수업을 듣고 준비를 하고, 관련 자격증을 준비해서 취득하는 시간을 보냈습니다.

그러고 실전이라고 생각하는 회사에 나가 일을 하면서 공부하고 자격증을 취득한 것이 도움이되었지만, 실전에 나가보니 더 많은 공부가 필요하고 실전 경험을 쌓아야 한다고 생각이 들었습니다. 저에게 있어서 현장실습은 계속해서 나아가 부딪혀봐야하기 때문에 실전이라고 생각합니다.', '물류시스템공학과', '4학년'),
  (11, 21, 9, '콘텐츠팀', ARRAY['저는 매주 작성하는 게시글 사진 사용 허가와 SNS 카드뉴스 제작을 담당했습니다. 매주 화요일, 금요일 두 번의 게시를 위해 회의를 통해 게시글 주제를 선정하고 작성된 글의 초안에 어울리는 사진을 데스크 리서치를 통해 허가받아 업로드 했습니다. 게시글 작성 이후에는 인스타그램과 페이스북에 제작할 카드뉴스를 제작했습니다. 디자인 툴을 이용해 알맞은 문구와 사진을 삽입해 제작을 마쳤습니다. 이후, 인스타그램과 페이스북에 업로드해 광고 집행을 통한 반응과 인사이트 통계도 확인했습니다.']::text[], ARRAY['게시글을 작성', '카드뉴스를 제작', '썸네일 제작']::text[], 11, '길잡이', '(주)위아프렌즈는 전 세계 사람들을 친구로 만들어 주겠다는 비전을 가지고 방한외국인을 위한 콘텐츠&쿠폰 혜택 어플리케이션 ''트리프렌드''와 서울을 관광 중이거나 체류 중인 외국인들을 위한 등산 장비 대여 및 코스 안내 등의 도움을 주는 ''서울 도심 등산관광센터''를 운영하고 있습니다.

(주)위아프렌즈 콘텐츠 마케팅 팀은 매주 외국인 대상으로 한국의 명장과 문화 등을 소개하는 게시글을 작성해 ''트리프렌드'' 어플리케이션, 홈페이지, 인스타그램 카드뉴스 형식으로 콘텐츠를 생산합니다.', '처음 며칠은 업무를 익히고 적응하기에 바빠 모든 일이 새로웠고, 마케팅 직무를 처음으로 실무에 적용시켜 일할 수 있어 기쁜 마음이었습니다. 저의 첫 게시글이 업로드 되던 날이 가장 인상 깊고 기억에 남는 순간이었습니다. 제 노력이 담긴 결과물을 보니 기뻤고, 게시글을 가족한테 공유했던 기억이 납니다.

이번 현장실습을 통해 컨텐츠 제작을 위한 여러 디자인 툴 프로그램을 익힐 수 있었습니다. 게시글을 작성할 때, 카드뉴스를 제작할 때, 썸네일 제작할 때 등 적재적소에 현장에서 사용하는 여러 디자인 툴을 익히며 효율적인 업무를 배울 수 있었습니다.', '저도 지원 준비 단계부터 막막하고 ''과연 내가 할 수 있을까?'' 하는 생각으로 가득했습니다. 그러나 한 발자국씩 해내고 또 교수님의 조언과 도움으로 합격을 이뤄낼 수 있었습니다. 인턴경험이 없는 학생들도 겁먹지 않고 자신있게 신청해보면 좋겠습니다. 서류와 면접과정에서도 최선을 다해 답변하는 모습과 준비된 성실성을 보여준다면 충분히 합격할 수 있을 것입니다. 학교에 다니면서 실무경험을 쌓을 수 있는 최고의 기회이니 많은 학우분들께서 다양하고 폭 넓은 경험을 쌓길 바라는 마음입니다.', '경영학부', '4학년'),
  (12, 22, 1, '광고사업부', ARRAY['투썸플레이스 인스타그램 콘텐츠 기획 및 운영', '광고 소재 기획 및 발행', '광고 성과 모니터링, 효과적인 콘텐츠 전략 제안', '광고 소재 기획 및 집행']::text[], ARRAY['인스타그램을 활용한 디지털 콘텐츠 앵글 구성과 기획', '투썸플레이스 월간 촬영', '엘리베이터 광고와 홍대입구역 OOH 광고 소재를 직접 기획']::text[], 1, '기회', '더에스엠씨는 디지털 콘텐츠 제작 전반에 필요한 모든 기획, 제작, 확산을 진행하며 효율적이고 효과적인 마케팅 솔루션을 제안하는 회사입니다. 연간 150여 개의 클라이언트 특성에 맞는 커뮤니케이션 사례를 만들며 콘텐츠의 힘으로 브랜드와 소비자를 연결합니다. 광고사업부는 투썸플레이스, 노브랜드, 다이소 등 다양한 소비재 및 유통 브랜드를 고객사로 두고 있는 광고 콘텐츠를 기획하고 운영하는 부서입니다.', '4개월간의 실습은 전공을 실무에 적용해 볼 수 있었던 의미 있는 시간이었습니다. 인스타그램을 활용한 디지털 콘텐츠 앵글 구성과 기획 과정을 통해 광고 업무에 대한 이해를 높일 수 있었으며, 광고 대행사의 전반적인 업무 흐름도 경험할 수 있었습니다. 또한 모니터링과 정보 수집이 대행사에서 가장 기본적이고 중요한 업무임을 깨닫게 되었고, 투썸플레이스 월간 촬영을 통해 푸드 스타일리스트 및 촬영 작가와 소통하며 협업의 중요성을 배울 수 있었습니다. 엘리베이터 광고와 홍대입구역 OOH 광고 소재를 직접 기획해 본 경험 역시 뜻깊었습니다.', '현장실습학기제에 참여하며 전공 역량을 점검할 수 있었고, 실무를 직접 경험하며 학교에서 배운 내용을 현장에 적용해 볼 수 있었습니다. 이러한 경험은 업무에 대한 이해를 높이는 데 도움이 되었으며, 앞으로의 진로를 구체적으로 고민해 보는 계기가 되는 소중한 기회가 되었습니다.', '광고홍보콘텐츠학과', '4학년'),
  (13, 22, 3, 'OL디자인실', ARRAY['디자인 기획부터 출고까지 전 과정 보조', '업무 우선순위 설정', '디자인 기획, 샘플링, 자재 수급, 출고 사이클 관찰', '공정상 오류나 데드라인 압박 등 다양한 변수 대처 및 프로젝트 지원']::text[], '{}'::text[], 5, '경험 이상', '오뷔엘알은 기획부터 출고까지의 빠른 생산 사이클을 기반으로, 디자이너의 창의적인 아이디어가 실제 작품으로 구현되는 생생한 현장감을 가진 기업입니다. 매 시즌 치열한 고민과 신속한 의사결정을 통해 시장의 흐름에 민감하게 반응하며 성장하고 있습니다. OL디자인실은 기획 단계부터 최종 출고에 이르기까지, 디자인의 실현 가능성을 점검하고 생산 공정 전반을 관리하는 중추적인 역할을 하고 있습니다.', '디자이너마다 다른 호흡을 맞추는 일은 매 순간 긴장의 연속이었고, 특히 밀려드는 시즌 준비는 결코 만만치 않은 과정이었습니다. 그 과정 속에서 하나의 의상이 세상에 나오기까지 얼마나 많은 사람들의 인내와 손길이 필요한지 절실히 느낄 수 있었습니다. 예상치 못한 변수로 인해 초반에는 스스로의 업무 능력을 자책하기도 했지만, 문제를 하나씩 해결해 나가며 주도적으로 대처하는 법을 배울 수 있었습니다. 이는 단순히 업무를 보조하는 시간을 넘어, 브랜드의 완성도를 지탱하기 위해 감내해야 할 책임의 무게를 체감하는 과정이었습니다. 비록 업무량으로 몸은 고되었지만, 제품을 무사히 출고했을 때의 쾌감은 이 직무의 매력을 충분히 느끼게 해주었습니다.', '실무를 처음 접하면 당황스러울 만큼 업무가 긴박하게 돌아가며, 방대한 업무량과 낯선 실무 프로세스에 적응하는 데 어려움을 느끼기 쉽습니다. 그러나 이러한 고비를 넘기고 나면 책상 앞에서는 배울 수 없는 실제 디자인의 흐름과 현장의 생동감을 몸소 체득할 수 있습니다. 나아가 단순히 주어진 일을 수행하는 단계를 넘어 실무 전반을 꿰뚫어 보는 시각을 기르고 싶은 이들에게, 이 과정은 무엇보다 확실한 밑거름이 되어 줄 것입니다.', '공연예술학부', '4학년'),
  (14, 22, 7, '마케팅팀', ARRAY['신제품 기획과 마케팅 업무 전반 보조', '시장 및 경쟁 제품 분석을 통한 신제품 기획 지원', '제품 정보 정리 및 자료 리서치 임무', '콘텐츠 기획 보조']::text[], ARRAY['자사몰 및 SNS 콘텐츠 기획 보조 업무를 수행', '실습 기간 동안 담당했던 자료가 실제 업무에 활용']::text[], 9, '진로를 구체화 할 수 있었던 경험', '원오세븐은 전통 발효 원료를 현대적인 스킨케어 기술로 재해석한 코스메틱 브랜드로, 오랜 시간 숙성된 발효 식초 성분을 핵심 원료로 활용한 제품을 선보이고 있습니다. 전통의 지혜와 과학적 연구를 결합한 피부 솔루션을 지향합니다. 국내를 넘어 해외 시장에서도 한국 발효 뷰티 브랜드로서 인지도를 확대하고 있습니다 원오세븐의 마케팅팀은 브랜드 전략 수립과 신제품 기획, 마케팅 콘텐츠 운영을 담당하는 부서입니다.', '가장 인상 깊었던 점은 신제품 기획과 마케팅 업무가 분리된 것이 아니라, 시장 조사부터 제품 콘셉트 설정, 콘텐츠 기획, 소비자 커뮤니케이션까지 유기적으로 연결되어 진행된다는 점이었습니다. 자사몰 및 SNS 콘텐츠 기획 보조 업무를 수행하며, 제품의 강점을 단순히 나열하는 것이 아니라 브랜드 철학을 소비자의 언어로 재해석하는 과정의 중요성을 배울 수 있었습니다. 실습 기간 동안 담당했던 자료가 실제 업무에 활용되는 것을 보며 큰 보람을 느꼈고, 전공과 연계된 다양한 실무 역량을 습득할 수 있었습니다. 이번 실습을 통해 마케팅 및 신제품 기획 직무에 대한 관심과 적성을 더욱 명확히 할 수 있었습니다.', '현장실습은 학교에서 배운 이론이 실제 회사 업무에서 어떻게 활용되는지를 직접 확인할 수 있는 경험이라고 생각합니다. 실습에 관심 있는 학생들에게는 이를 막연히 어렵게 느끼기보다, 자신의 전공과 관심 분야를 실제 업무로 시험해 볼 수 있는 기회로 받아들이기를 권하고 싶습니다. 이번 현장실습은 색조 화장품 마케팅 분야를 목표로 한 진로 방향을 더욱 구체화하는 계기가 되었으며, 전공 역량을 실무 경험으로 확장할 수 있었던 의미 있는 시간이었습니다.', '메이크업디자인학과', '4학년'),
  (15, 22, 10, '마케팅솔루션팀', ARRAY['굿즈 및 팝업스토어, 축제디자인', '촬영 및 사업 보조', '행사 및 팝업스토어 운영', '버스킹 운영 및 공연 현장 보조']::text[], ARRAY['굿즈 디자인, 팝업스토어, 행사 운영, 촬영 보조 등 다양한 업무를 수행']::text[], 11, '성장과 깨달음의 과정', '스미스는 자체 기획부터 운영 홍보까지 대행사업 운영 토탈 솔루션으로 성공적인 프로젝트를 수행합니다. 온라인 콘텐츠 기획, 운영, 미디어 콘텐츠를 활용해 다양한 타겟에 어필이 가능한 최적의 콘텐츠를 만듭니다. 마케팅솔루션팀은 IMC마케팅 부분 프로젝트별 기획 및 운영 보조 업무, IP활용 마케팅, 브랜드 팝업 스토어 운영 지원, 행사기획, NCN 마케팅 지원 및 자사 홍보 지원을 하는 부서입니다.', '행사 대행업체 현장실습을 통해 콘텐츠와 행사가 기획부터 제작, 운영까지 완성되는 전 과정을 경험했습니다. 굿즈 디자인, 팝업스토어, 행사 운영, 촬영 보조 등 다양한 업무를 수행하며 콘텐츠가 공간·사람·브랜드와 유기적으로 연결된다는 점을 이해할 수 있었습니다. 또한 브랜드 아이덴티티를 반영해 실제 제작과 설치까지 고려해야 하는 실무적 사고의 중요성을 배울 수 있었습니다. 현장 프로젝트를 통해 협업과 즉각적인 판단, 현장 대응 역량의 중요성을 체감했으며, 이번 실습을 통해 기획력과 의사소통 능력, 책임감이 성장하고 콘텐츠 기획·제작 분야에 대한 이해가 깊어졌습니다.', '스미스 주식회사에서 한 학기 동안 실습하며 행사 기획부터 디자인, 운영, 마무리까지 전 과정을 현장에서 직접 경험했습니다. 이 과정에서 고객·협력사·내부 팀 간의 원활한 소통이 행사 성과를 좌우한다는 점을 체감하며 커뮤니케이션 능력의 중요성을 깨달았습니다. 또한 작은 업무 하나하나가 전체 결과에 영향을 미친다는 사실을 느끼며 책임감과 집중력이 크게 향상되었습니다. 이번 실습을 통해 진로에 대한 확신을 얻었고, 실무 역량을 갖춘 인재로 성장하고자 하는 목표를 더욱 분명히 할 수 있었습니다.', '아트앤테크놀로지학과', '3학년'),
  (16, 22, 11, '사업', ARRAY['거래 제의서, 피치덱 등 영업 문서 작성 및 발송', '전시회/박람회 참가 및 해외 기업 B2B 미팅', '관심 기업 대상 화상회의 알선 및 통역', '기술 실증 데이터 클러스터 분석 및 보고서 작성']::text[], ARRAY['총 6개의 프로젝트에 참여', '2개 프로젝트에서는 프로젝트 매니저로서 용역 계약부터 완료 단계까지 전 과정을 담당', '기술 실증 관련 군집분석 보고서 작성']::text[], 17, '북극성', '델타텍코리아는 기술거래 기관이자, 디지털 기술무역 대행사로서 오픈 이노베이션 행사 개최 및 자사 기술거래 시장을 운영하며 다양한 수출바우처 사업에 참여, 국내 스타트업들을 해외 시장에 진출시키고 있습니다. 사업 부문은 진행 프로젝트의 주관기관 및 수혜기업의 시장조사 및 잠재 거래처 발굴, 비즈니스 문서 작성, 해외 기업과의 화상미팅 및 계약 알선 등 해외 시장 진출 과정의 A to Z를 담당합니다.', '현장실습 4개월 동안 총 6개의 프로젝트에 참여했으며, 이 중 2개 프로젝트에서는 프로젝트 매니저로서 용역 계약부터 완료 단계까지 전 과정을 담당했습니다. 매일 전 세계 수십 개 기업과 이메일 및 화상 미팅을 통해 소통하며 B2B 영업을 경험했고, 기술 실증 관련 군집분석 보고서 작성과 전시회 부스 운영 등 다양한 실무를 수행했습니다. 바쁜 일정의 연속이었지만, 그 과정에서 실무 역량과 경력을 함께 성장시키며 개인적으로도 한층 성숙해질 수 있었습니다.', '델타텍코리아에서 4개월간 함께한 시간은 막연하고 불투명했던 제 진로와 목표에 방향을 제시해 준 북극성과 같은 경험이었습니다. B2B 해외 영업을 비롯해 기술무역, 디지털 마케팅 등 폭넓은 업계 지식과 실무 역량을 기를 수 있었으며, 다양한 프로젝트에 PA로 참여하는 것은 물론 역량에 따라 PM 역할까지 수행할 기회를 얻었습니다. 이를 통해 한 번의 인턴 경험만으로도 2~3년 차 경력자에 준하는 성장을 이룰 수 있었습니다.', '공공인재학부', '4학년'),
  (17, 22, 9, '콘텐츠팀', ARRAY['외국인들을 위한 콘텐츠 제작 보조', '행사 진행을 위한 사무 보조', '정기 콘텐츠 업로드를 위한 제작 보조', '신규 서비스 런칭/진행을 위한 업무 보조']::text[], ARRAY['서울관광재단 협업 프로젝트와 K-Xplore 신규 서비스 런칭에 참여']::text[], 19, '첫 단추', '위아프렌즈는 AI 기술 기반의 글로벌 소셜 플랫폼 기업으로서 방한 외국인의 여행&소셜 매칭 앱과 현지 체험 프로그램, 투어, 이벤트 연결 서비스를 운영하고 있습니다 콘텐츠팀은 방한 외국인을 위한 한국 여행 콘텐츠 제작 보조를 하며 데스크 리서치 및 현장 취재, 콘텐츠 제작 및 사무 보조 업무를 하고 있습니다.', '스타트업 환경 속에서 스스로 업무를 발굴하고 수행하며 성장한 경험이 특히 인상 깊었습니다. 서울관광재단 협업 프로젝트와 K-Xplore 신규 서비스 런칭에 참여해 성과를 만들어냈으며, 직접 의견을 제시하고 책임지고 실행해 결과를 확인한 과정에서 큰 보람을 느꼈습니다. 또한 구글 협업 도구, 노션, 구글 시트 앱 스크립트 등을 활용해 콘텐츠 기획·제작과 데이터 분석 역량을 강화했고, 회의 참여와 KPI 기반 업무 수행을 통해 기획력과 의사소통 능력, 데이터 중심의 의사결정 역량을 함께 기를 수 있었습니다.', '현장실습이나 인턴십을 너무 어렵게만 생각하지 않았으면 합니다. 먼저 자신이 어떤 일을 하고 싶은지 고민한 뒤, 이에 맞는 회사에서 해당 직무가 자신과 잘 맞는지, 또 어떤 가치와 환경을 중요하게 봐야 하는지를 직접 확인해 볼 수 있는 기회로 활용해 보기를 권합니다. 이러한 경험은 앞으로의 진로를 보다 구체화하는 데에도 큰 도움이 될 것입니다.', '경영학부', '4학년');

